import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import '../models/task.dart';

class TaskTile extends StatelessWidget { final TaskItem task; final VoidCallback onToggle,onEdit,onDelete; const TaskTile({super.key,required this.task,required this.onToggle,required this.onEdit,required this.onDelete}); @override Widget build(BuildContext context){final colors=Theme.of(context).colorScheme; final priorityColor=task.priority==2?Colors.red:task.priority==1?Colors.orange:Colors.green;return Card(margin:const EdgeInsets.symmetric(vertical:5),child:Padding(padding:const EdgeInsets.symmetric(vertical:7,horizontal:8),child:Row(children:[IconButton(onPressed:onToggle,icon:AnimatedSwitcher(duration:const Duration(milliseconds:180),child:Icon(task.completed?Icons.check_circle:Icons.circle_outlined,key:ValueKey(task.completed),color:task.completed?colors.primary:null,size:25))),Expanded(child:InkWell(onTap:onEdit,child:Padding(padding:const EdgeInsets.symmetric(vertical:8),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(task.title,style:Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight:FontWeight.w700,decoration:task.completed?TextDecoration.lineThrough:null,color:task.completed?colors.onSurfaceVariant:null)),if(task.description.isNotEmpty)Padding(padding:const EdgeInsets.only(top:4),child:Text(task.description,maxLines:2,overflow:TextOverflow.ellipsis,style:Theme.of(context).textTheme.bodySmall)),const SizedBox(height:7),Wrap(spacing:7,runSpacing:5,children:[_pill(context,task.category,colors.primary),_pill(context,task.priority==2?'مرتفعة':task.priority==1?'متوسطة':'منخفضة',priorityColor),if(task.dueAt!=null)_pill(context,DateFormat('y/MM/dd').format(task.dueAt!),colors.onSurfaceVariant)])])))),PopupMenuButton<String>(onSelected:(v){if(v=='edit')onEdit();else onDelete();},itemBuilder:(_)=>const [PopupMenuItem(value:'edit',child:Text('تعديل')),PopupMenuItem(value:'delete',child:Text('حذف'))])])));}
 Widget _pill(BuildContext c,String text,Color color)=>Container(padding:const EdgeInsets.symmetric(horizontal:8,vertical:3),decoration:BoxDecoration(color:color.withOpacity(.10),borderRadius:BorderRadius.circular(20)),child:Text(text,style:TextStyle(fontSize:11,color:color,fontWeight:FontWeight.w600))); }
